import React, {useEffect, useState} from 'react'
import {Link} from 'react-router-dom'
import {useAuth} from '../auth'
import Recipe from './Recipe'
import {Button, Form, Modal} from 'react-bootstrap'
import {useForm} from 'react-hook-form'


const LoggedinHome = () => {
    const [recipes, setRecipes] = useState([]);
    const [show, setShow] = useState(false)
    const{register, reset, handleSubmit, setValue, formState:{errors}}= useForm()

    useEffect(
        () => {
            fetch('/recipe/recipes')
                .then(res => res.json())
                .then(data => {
                    setRecipes(data)
                })
                .catch(err => console.log(err))
        }, []
    );

    const closeModal = () => {
        setShow(false)
    }
    const showModal = (id) => {
        console.log("hello" + id)
        setShow(true)

        recipes.map(
            (recipe)=>{
                if(recipe.id==id){
                    setValue('title',recipe.title)
                    setValue('description')
                }
            }
        )

    }
    const updateRecipe=(data)=>{
        console.log(
            data
        )
    }

    return (
        <div className={"recipes container"}>
            <Modal
                show={show}
                size={"lg"}
                onHide={closeModal}
            >
                <Modal.Header closeButton>
                    <Modal.Title>
                        Update Recipe
                    </Modal.Title>

                </Modal.Header>
                <Modal.Body>
                    <form>
                        <Form.Group>
                            <Form.Label>Title</Form.Label>
                            <Form.Control type={'Text'}
                                          {...register('title', {required: true, maxLength: 25})}

                            />
                        </Form.Group>
                        {errors.title && <p style={{color: 'red'}}><small>Title is required</small></p>}
                        {errors.title?.type === "maxLength" &&
                        <p style={{color: 'red'}}><small>Title should be less than 25 characters</small></p>}
                        <Form.Group>
                            <Form.Label>Description</Form.Label>
                            <Form.Control as={"textarea"} rows={5}
                                          {...register('description', {required: true, maxLength: 255})}

                            />
                        </Form.Group>
                        {errors.description && <p style={{color: 'red'}}><small>Description is required</small></p>}
                        {errors.description?.type === "maxLength" &&
                        <p style={{color: 'red'}}><small>Description should be less than 255 characters</small></p>}
                        <br></br>
                        <Form.Group>
                            <Button variant={"primary"} onClick={handleSubmit(updateRecipe)}>
                                Save
                            </Button>
                        </Form.Group>
                    </form>
                </Modal.Body>

            </Modal>
            <h1>List of Recipes</h1>
            {
                recipes.map(
                    (recipe, index) => (
                        <Recipe title={recipe.title}
                                key={index}
                                description={recipe.description}
                                onClick={()=>{showModal(recipe.id)}}
                        />
                    )
                )

            }

        </div>
    )
}

const LoggedOutHome = () => {
    return (
        <div className="home container">
            <h1 className={'heading'}>Welcome to the Recipes</h1>
            <Link to={"/signup"} className={"btn btn-primary btn-lg"}>Get Started</Link>
        </div>
    )
}


const HomePage = () => {
    const [logged] = useAuth()
    return (
        <div>
            {logged ? <LoggedinHome/> : <LoggedOutHome/>}
        </div>

    )
}

export default HomePage
